use verus::prelude::*;

verus! {

    /// Given a non‐empty array `a` and a starting index `lo < a.len()`,
    /// returns an index `minIdx` in `[lo, a.len())` such that
    /// `a[minIdx]` is the minimum over `a[lo..]`.
    fn find_min(a: &[int], lo: usize) -> (minIdx: usize)
        requires
            // preconditions
            lo < a.len()
        ensures
            // the result is in bounds of the suffix
            lo <= minIdx && minIdx < a.len(),
        ensures
            // the result indeed points at a minimal element
            forall |j: usize| lo <= j && j < a.len() ==> a[minIdx] <= a[j],
    {
        let mut idx: usize = lo;
        let mut i:   usize = lo + 1;
        let n:       usize = a.len();

        // Loop over i in [lo+1, n), maintaining that
        //   idx ∈ [lo,n) and
        //   for all j in [lo, i), a[idx] ≤ a[j].
        while i < n
            invariant lo <= idx && idx < n
            invariant lo <= i   && i   <= n
            invariant forall |j: usize| lo <= j && j < i ==> a[idx] <= a[j]
            decreases n - i
        {
            if a[i] < a[idx] {
                idx = i;
            }
            i += 1;
        }

        // at this point i == n, so idx is the index of a minimal element in a[lo..]
        minIdx = idx;
    }

}